const { execFileSync } = require('child_process');

const key = $credentials.stripeApi.secretKey;
if (!key || !key.startsWith('rk_')) {
  throw new Error('Use a Stripe restricted read key (rk_test_ or rk_live_) in this credential — not sk_.');
}

const stdout = execFileSync('npx', ['-y', 'graphmyanything-stripe', 'sync'], {
  env: { ...process.env, STRIPE_RESTRICTED_KEY: key },
  encoding: 'utf8',
  maxBuffer: 16 * 1024 * 1024,
});

const result = JSON.parse(stdout.trim());
return [{ json: result }];
